CREATE TABLE control_operators(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,display_name text NOT NULL,external_subject text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,merchant_id));
ALTER TABLE api_keys ADD COLUMN operator_id text;
ALTER TABLE api_keys ADD CONSTRAINT key_operator_owner FOREIGN KEY(operator_id,merchant_id) REFERENCES control_operators(id,merchant_id);
CREATE FUNCTION guard_operator_binding() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.operator_id IS DISTINCT FROM OLD.operator_id THEN RAISE EXCEPTION 'Operator key binding is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_operator_binding BEFORE UPDATE ON api_keys FOR EACH ROW EXECUTE FUNCTION guard_operator_binding();
CREATE TABLE merchant_controls(merchant_id text PRIMARY KEY REFERENCES merchants,state text NOT NULL DEFAULT 'sandbox' CHECK(state IN ('sandbox','staging_active','paused')),revision integer NOT NULL DEFAULT 0,policy jsonb NOT NULL DEFAULT '{"caps":[]}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE control_evidence(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,customer_id text,kind text NOT NULL CHECK(kind IN ('kyb','kyc','screening','custody','security','legal','partner')),outcome text NOT NULL CHECK(outcome IN ('checked','review','rejected')),mode text NOT NULL DEFAULT 'staging' CHECK(mode='staging'),reference text NOT NULL,reason text NOT NULL,operator_id text NOT NULL REFERENCES control_operators,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(customer_id,merchant_id) REFERENCES customers(id,merchant_id),CHECK(expires_at>created_at));
CREATE TRIGGER immutable_control_evidence BEFORE UPDATE OR DELETE ON control_evidence FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE control_requests(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,action text NOT NULL CHECK(action IN ('start_staging','resume','change_caps')),policy jsonb NOT NULL,base_revision integer NOT NULL,reason text NOT NULL,requested_by text NOT NULL REFERENCES control_operators,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),reviewed_by text REFERENCES control_operators,review_reason text,expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,CHECK(reviewed_by IS NULL OR reviewed_by<>requested_by));
CREATE FUNCTION guard_control_request() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.id,NEW.merchant_id,NEW.action,NEW.policy,NEW.base_revision,NEW.reason,NEW.requested_by,NEW.expires_at,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.merchant_id,OLD.action,OLD.policy,OLD.base_revision,OLD.reason,OLD.requested_by,OLD.expires_at,OLD.created_at) OR OLD.state<>'pending' OR NEW.state NOT IN ('approved','rejected') OR NEW.reviewed_by IS NULL OR NEW.review_reason IS NULL THEN RAISE EXCEPTION 'Approval request is immutable or terminal'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_control_request BEFORE UPDATE ON control_requests FOR EACH ROW EXECUTE FUNCTION guard_control_request();
CREATE TRIGGER no_delete_control_requests BEFORE DELETE ON control_requests FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE control_audit(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,actor_key_id text NOT NULL REFERENCES api_keys,operator_id text REFERENCES control_operators,action text NOT NULL,resource_id text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_control_audit BEFORE UPDATE OR DELETE ON control_audit FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE pilot_usage(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,resource_id text NOT NULL UNIQUE,asset text NOT NULL CHECK(asset IN ('NGN','KES','GHS','USDC','KUSD')),amount_minor numeric(30,0) NOT NULL CHECK(amount_minor>0),day date NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pilot_usage_day ON pilot_usage(merchant_id,day,asset);
CREATE TRIGGER immutable_pilot_usage BEFORE UPDATE OR DELETE ON pilot_usage FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
CREATE TABLE daily_control_reports(id text PRIMARY KEY,merchant_id text NOT NULL REFERENCES merchants,day date NOT NULL,control_clean boolean NOT NULL,scope text NOT NULL DEFAULT 'ledger_and_receipt_controls' CHECK(scope='ledger_and_receipt_controls'),provider_cash_complete boolean NOT NULL DEFAULT false CHECK(provider_cash_complete=false),data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_daily_reports BEFORE UPDATE OR DELETE ON daily_control_reports FOR EACH ROW EXECUTE FUNCTION immutable_financial_record();
